      pasalDiujikan: [ { pasal: "Pasal 94", ringkas: "penyetoran pajak masa paling lambat tanggal 15 bulan berikutnya (sebelum 2025: tanggal 10)" }, { pasal: "Pasal 100", ringkas: "jatuh tempo setor pada hari libur bergeser ke hari kerja berikutnya" }, { pasal: "Pasal 171", ringkas: "SPT Masa PPh paling lama 20 hari setelah masa berakhir; SPT Masa PPN akhir bulan berikutnya" }, { pasal: "Pasal 238 sampai 240 (dan Pasal 1 angka 149)", ringkas: "penjualan saham Perseroan (perseroan terbatas dalam negeri yang bukan emiten atau perusahaan publik) oleh WPLN selain BUT: PPh 26 20% × perkiraan penghasilan neto 25% dari harga jual = 5%, final; bagi penduduk negara mitra P3B hanya dipotong bila hak pemajakan ada pada Indonesia; dipotong pembeli, dan bila pembeli WPLN, Perseroan ditunjuk sebagai pemungut; Perseroan hanya mencatat pemindahan hak bila PPh-nya sudah lunas. Menggantikan KMK 434/KMK.04/1999 (dicabut Pasal 483 angka 3)" }, { pasal: "Ketentuan NPPN dan akun WP", ringkas: "pemberitahuan NPPN dalam 3 bulan pertama tahun pajak; akun WP, sertifikat elektronik, kode otorisasi; seluruh hak/kewajiban elektronik sejak Masa Januari 2025" }, { pasal: "Pengembalian pajak yang seharusnya tidak terutang (nomor pasal ◐)", ringkas: "menggantikan PMK 187/PMK.03/2015: permohonan pengembalian atas pajak yang seharusnya tidak terutang, termasuk PPh 26 yang dipotong melebihi tarif P3B, diajukan melalui Coretax" }, { pasal: "Ketentuan PPN yang dialihkan (nomor pasal ◐, kecuali Pasal 324)", ringkas: "pemungutan PPN PMSE (menggantikan PMK 60/PMK.03/2022), PPN kegiatan membangun sendiri Pasal 324 (menggantikan PMK 61/PMK.03/2022; besaran disesuaikan PMK 11/2025, efektif 2,2%), dan batasan kegiatan serta jenis JKP yang atas ekspornya dikenai PPN 0% (menggantikan PMK 32/PMK.010/2019)" } ],
