      pasalDiujikan: [ { pasal: "Klasifikasi", ringkas: "perkebunan, perhutanan, pertambangan minerba, migas, panas bumi, dan sektor lainnya (perikanan, pipa, kabel, jalan tol, dsb.)" }, { pasal: "NJOP bumi", ringkas: "areal × nilai per m²; areal produktif perkebunan = tanah (perbandingan harga) + pengembangan tanah berdasarkan Biaya Investasi Tanaman (Pasal 14 ayat (2) huruf a); tubuh bumi operasi produksi pertambangan memakai Nilai Jual Pengganti = pendapatan bersih minerba atau pendapatan migas × Angka Kapitalisasi (Pasal 21 ayat (7) huruf b, Pasal 17 ayat (7) huruf b)" }, { pasal: "SPOP (Pasal 39 s.t.d.d. PMK 234/2022)", ringkas: "SPPT diterbitkan berdasarkan SPOP yang disampaikan Subjek Pajak atau Wajib Pajak ke KPP; DJP dapat melakukan penilaian lapangan dan, bila SPOP tidak mencerminkan keadaan sebenarnya, menerbitkan SPPT berdasarkan data penilaian lapangan. Tenggat pengembalian SPOP tidak diatur di PMK ini" } ],
